import { PerlinNoise, type PerlinNoiseProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

interface ShaderPerlinNoiseProps
  extends Omit<PerlinNoiseProps, "frame" | "ref"> {}

function ShaderPerlinNoiseBase({
  speed = 1,
  colorBack = "#12121a",
  colorFront = "#6a6a85",
  proportion = 0.35,
  softness = 0.1,
  className,
  ...rest
}: ShaderPerlinNoiseProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-perlin-noise"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <PerlinNoise
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colorBack={colorBack}
        colorFront={colorFront}
        proportion={proportion}
        softness={softness}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  proportion: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.35,
    description: "Proportion",
    hiddenFromList: false,
  },
  softness: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.1,
    description: "Softness",
    hiddenFromList: false,
  },
  colorBack: {
    type: "color",
    default: "#12121a",
    description: "Background",
  },
  colorFront: {
    type: "color",
    default: "#6a6a85",
    description: "Front",
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","proportion","softness","colorBack","colorFront"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  proportion: 0.35,
  softness: 0.1,
  colorBack: "#12121a",
  colorFront: "#6a6a85",
};

type ShaderPerlinNoiseElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderPerlinNoiseBase>;

const ShaderPerlinNoiseInner = forwardRef<
  HTMLDivElement,
  ShaderPerlinNoiseElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderPerlinNoise>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderPerlinNoiseBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderPerlinNoiseBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderPerlinNoise = Interactive.withSchema({
  Component: ShaderPerlinNoiseInner,
  componentName: "<ShaderPerlinNoise>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
